internal class GUPPricingRuleBuilder_PriceTermJournalTrans extends GUPPricingRuleBuilder
{
    private GUPPriceTermJournalTable journalTable;

}

Method.Source:
public static void main(Args args)
{
    GUPPricingRuleBuilder_PriceTermJournalTrans createRule;
    createRule = new GUPPricingRuleBuilder_PriceTermJournalTrans(args.record());

    createRule.createRecord();
}

public void initMasterRecord()
{
    GUPPriceTermJournalTrans journalTrans;

    journalTrans.clear();
    journalTrans.AgreementId = this.journalTable.AgreementId;
    journalTrans.initfromGUPPriceTermJournalTable(this.journalTable);
    journalTrans.LineNum = GUPPriceTermJournalTrans::lastLineNum(journalTable.AgreementId) + SystemParameters::getSystemLineNumberIncrement();

    this.masterRecord = journalTrans;
}

public void linkPricingRule(GUPPricingRule _pricingRule)
{
    if (this.dialogOk && _pricingRule)
    {
        GUPPriceTermJournalTrans createdJournalTrans = masterRecord;

        createdJournalTrans.PricingRule = _pricingRule.RecId;
    }
}
